{
  "question_stem": "In the case report, fondaparinux was chosen only after addressing the patient's mildly reduced antithrombin level. What adjunctive treatment was administered before starting fondaparinux?",
  "target": " AT concentrate",
  "correct_label": "A",
  "options": {
    "A": " AT concentrate",
    "B": "protamine sulfate",
    "C": "fresh frozen plasma",
    "D": "platelet transfusion",
    "E": "vitamin K"
  },
  "rationale": "Fondaparinux is an indirect antithrombin-dependent factor Xa inhibitor, so the report describes correcting the mildly reduced antithrombin level first by giving AT concentrate before initiating fondaparinux."
}

{
  "question_stem": "In the case report, which classic Chiari headache feature was absent when compared with the typical pattern described in the literature?",
  "target": " Valsalva-precipitated headache",
  "correct_label": "E",
  "options": {
    "A": " occipital headache",
    "B": " cough-precipitated headache",
    "C": " unilateral pulsating headache",
    "D": " morning headache",
    "E": " Valsalva-precipitated headache"
  },
  "rationale": "The report states that the cardinal Chiari headache is a paroxysmal occipital headache precipitated by Valsalva manoeuvres, but this patient's headaches were not exacerbated by coughing, straining, or other Valsalva manoeuvres. Therefore, the absent classic feature was Valsalva-precipitated headache."
}

{
  "question_stem": "Which syndrome pattern is suggested by preserved voluntary breathing but impaired automatic control during sleep or distraction in the reported case?",
  "target": " acquired central hypoventilation",
  "correct_label": "A",
  "options": {
    "A": " acquired central hypoventilation",
    "B": "congenital central hypoventilation syndrome",
    "C": "obstructive sleep apnea syndrome",
    "D": "central sleep apnea syndrome",
    "E": "obesity hypoventilation syndrome"
  },
  "rationale": "The case report states that preserved voluntary ventilation with loss of automatic respiratory drive during sleep or distraction strongly suggests an acquired central hypoventilation pattern (central alveolar hypoventilation syndrome, acquired Ondine’s curse)."
}

