  "options": {
    "A": "drug-induced IMNM",
    "B": "statin-associated IMNM",
    "C": " idiopathic IMNM",
    "D": "anti-HMGCR IMNM",
    "E": "paraneoplastic IMNM"
  },
  "rationale": "The rapid improvement after stopping semaglutide, along with brief steroid use and no additional IVIG, fits drug-induced IMNM more than idiopathic IMNM. Idiopathic IMNM typically requires prolonged, intensive immunosuppression, so it became less likely."
}

